package io.github.mesmerprism.rustyquest.shellcapabilities;
import android.os.Process;import java.io.*;import java.util.*;
final class AppSnapshot{
 static String capture(int shellPid){try{Map<String,String>m=new LinkedHashMap<>();for(String line:read("/proc/self/status").split("\n")){int c=line.indexOf(':');if(c>0){String k=line.substring(0,c);if(Arrays.asList("Uid","Gid","Groups","CapInh","CapPrm","CapEff","CapBnd","CapAmb","NoNewPrivs","Seccomp").contains(k))m.put(k,line.substring(c+1).trim());}}StringBuilder s=new StringBuilder("{\"uid\":").append(Process.myUid()).append(",\"pid\":").append(Process.myPid()).append(",\"selinux\":").append(ProbeCore.quote(read("/proc/self/attr/current").trim())).append(",\"boot_id_length\":").append(read("/proc/sys/kernel/random/boot_id").trim().length()).append(",\"boot_readable\":true,\"status\":{");int n=0;for(Map.Entry<String,String>e:m.entrySet()){if(n++>0)s.append(',');s.append(ProbeCore.quote(e.getKey())).append(':').append(ProbeCore.quote(e.getValue()));}s.append("},\"shell_proc_pid\":").append(shellPid);try{read("/proc/"+shellPid+"/stat");s.append(",\"shell_proc_readable\":true");}catch(Throwable x){s.append(",\"shell_proc_readable\":false,\"shell_proc_error\":").append(ProbeCore.quote(x.getClass().getName()+":"+x.getMessage()));}return s.append('}').toString();}catch(Throwable x){return "{\"error\":"+ProbeCore.quote(x.getClass().getName()+":"+x.getMessage())+"}";}}
 static String read(String p)throws Exception{StringBuilder b=new StringBuilder();try(BufferedReader in=new BufferedReader(new FileReader(p))){String l;while((l=in.readLine())!=null&&b.length()<16384)b.append(l).append('\n');}return b.toString();}
}
